insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0004-0000-4000-8000-000000000029', 'en', null, 'Introduction to Epidemiology', 'How populations stay healthy or fall ill: counting disease, comparing groups, spotting bias, and reasoning about cause without mistaking correlation for proof. This course teaches the reasoning of epidemiology for education only and is not medical advice. Structure adapted from the Johns Hopkins Bloomberg School of Public Health OpenCourseWare (CC BY-NC-SA 3.0); all explanations original.', null, 'foundations', 39, true, 'science', '{}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0004-0000-4000-8000-000000000029', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"Epidemiology is best described as the study of...","options":["how individual patients respond to a single drug","the distribution and determinants of health states in populations","the chemistry of the human immune system","how hospitals bill for services"],"answer":1,"explanation":"Epidemiology looks at whole populations - who gets a condition, where, when, and why - see ''What epidemiology is''."},{"prompt":"Prevalence differs from incidence because prevalence counts...","options":["only new cases in a period","all existing cases at a point in time","deaths only","recoveries only"],"answer":1,"explanation":"Prevalence is a snapshot of existing cases; incidence counts new cases over time - see ''Measures of disease frequency''."},{"prompt":"In a study that starts with people who already have a disease and looks backward at past exposures, the design is a...","options":["cohort study","case-control study","randomized trial","cross-sectional survey"],"answer":1,"explanation":"Case-control studies begin with cases and controls and look back at exposure history."},{"prompt":"In a 2x2 table with exposed cases a, exposed non-cases b, unexposed cases c, unexposed non-cases d, the odds ratio equals...","options":["(a/b) / (c/d)","(a*d) / (b*c)","a / (a+b)","(a+c) / (b+d)"],"answer":1,"explanation":"The odds ratio is the cross-product ad/bc - see ''Measures of association''."},{"prompt":"A confounder is a variable that...","options":["is caused only by the disease","is measured with a broken instrument","is associated with both the exposure and the outcome and distorts their relationship","always increases the true effect"],"answer":2,"explanation":"Confounding mixes a third factor into the exposure-outcome link - see ''Bias and confounding''."},{"prompt":"The sensitivity of a diagnostic test is the probability that...","options":["a healthy person tests negative","a person who tests positive truly has the disease","a person who truly has the disease tests positive","the test is cheap"],"answer":2,"explanation":"Sensitivity = true positives / all who truly have the disease - see ''Screening and diagnostic tests''."},{"prompt":"Of Bradford Hill''s considerations for causation, the one that is essentially required is...","options":["analogy","specificity","temporality (cause before effect)","elegance"],"answer":2,"explanation":"A cause must precede its effect in time; temporality is the one nearly non-negotiable criterion."},{"prompt":"If a pathogen has a basic reproduction number R0 of 4, the herd immunity threshold is roughly...","options":["25 percent","50 percent","75 percent","100 percent"],"answer":2,"explanation":"The threshold is 1 - 1/R0 = 1 - 1/4 = 0.75, i.e. about 75 percent immune - see ''Infectious disease dynamics''."}]}'::jsonb, null, 10),
  (2, 'What epidemiology is, and a short history', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Say in one sentence what epidemiology studies, name its two core questions, and place a few landmark investigations in order. Warm-up: from the diagnostic, is epidemiology about single patients or about populations? Remember, everything here is educational framing, not medical advice."},{"heading":"The idea","text":"Epidemiology is the study of the distribution and determinants of health-related states in populations, and the use of that knowledge to protect health. Distribution asks who is affected, where, and when - the descriptive side. Determinants ask why and how - the analytic side. The discipline treats a population, not one person, as the unit of concern, so its answers are patterns and comparisons rather than individual diagnoses. Two questions organize almost all of it: how much disease is there, and what is associated with getting it?"},{"heading":"Worked examples","text":"In 1854 John Snow mapped cholera deaths in London and noticed they clustered around one water pump on Broad Street; removing the pump handle was an early natural experiment linking contaminated water to disease before anyone had seen the bacterium. In the 1700s James Lind compared sailors given citrus against sailors given other remedies and found citrus cured scurvy - an early controlled comparison. In the mid-1900s the British Doctors Study followed thousands of physicians for years and tied cigarette smoking to lung cancer. Each example shares one move: compare groups that differ in an exposure, and watch how disease differs."},{"heading":"Your turn","text":"1) Name the descriptive triad of person, place, and what third element? 2) Was Snow''s pump-handle removal closer to a description or an intervention? 3) Which came first in Lind''s work - the comparison groups or the germ theory that explained them? 4) Is ''this town has more asthma than that town'' a descriptive or an analytic statement? 5) What is the unit epidemiology studies? Answers: 1) time. 2) an intervention (he changed something and watched the effect). 3) the comparison groups came first; the explanation came much later. 4) descriptive - it reports distribution without yet explaining why. 5) the population."},{"heading":"Common mistakes & exit ticket","text":"Mistake: reading a population risk as a personal certainty - a tripled group risk does not mean a given person will fall ill. Mistake: assuming a cluster proves a cause; a cluster is a starting clue, not a conclusion. Exit: (a) What are epidemiology''s two core questions? (b) Is a disease map descriptive or analytic? Answers: how much disease is there, and what is associated with getting it; descriptive."}]}'::jsonb, 'Epidemiology describes populations, not individuals. A statement like ''smokers have triple the risk'' is about a group average, not a prediction about any one person.', 12),
  (3, 'Measures of disease frequency: prevalence, incidence, rates', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Compute prevalence, cumulative incidence, and an incidence rate, and say which one a question calls for. Warm-up: if a survey today finds 300 people living with a condition in a town of 10,000, is that a snapshot or a count of new cases?"},{"heading":"The idea","text":"Prevalence is the fraction of a population that has a condition at a point in time: existing cases divided by the total population. Cumulative incidence (also called risk) is the fraction of an at-risk group that develops the condition over a defined period: new cases divided by the number at risk at the start. An incidence rate replaces that headcount denominator with person-time - the total time each person was followed while still at risk - so it handles people who join, leave, or fall ill partway through. Prevalence depends on both how fast people get a condition and how long they keep it; incidence measures only the arrival of new cases."},{"heading":"Worked examples","text":"A town of 10,000 is surveyed once. 300 people currently have condition X, so prevalence = 300 / 10,000 = 0.03 = 3 percent. Now follow the 9,700 people who were disease-free for one year; 50 of them develop X. Cumulative incidence = 50 / 9,700 = 0.00515, about 515 new cases per 100,000 per year. If instead those 9,700 people contributed 9,500 person-years of at-risk follow-up (some left early), the incidence rate = 50 / 9,500 = 0.00526 per person-year, i.e. about 5.3 cases per 1,000 person-years. Notice prevalence used the whole population as denominator, while both incidence measures used only those still at risk."},{"heading":"Your turn","text":"1) A clinic of 2,000 patients finds 120 with a chronic condition today - what is the prevalence? 2) Among 800 disease-free workers followed one year, 16 develop the condition; what is the cumulative incidence? 3) Which measure belongs in the denominator of an incidence rate - headcount or person-time? 4) A condition becomes far less deadly but no less common to catch; does its prevalence tend to rise or fall? 5) If 40 cases arise over 2,000 person-years, what is the rate per 1,000 person-years? Answers: 1) 120/2000 = 0.06 = 6 percent. 2) 16/800 = 0.02 = 2 percent. 3) person-time. 4) rise - people live longer with it, so more exist at any moment. 5) 40/2000 = 0.02 per person-year = 20 per 1,000 person-years."},{"heading":"Common mistakes & exit ticket","text":"Mistake: putting the whole population in an incidence denominator when only the disease-free are at risk. Mistake: calling prevalence a rate - it carries no time. Exit: (a) Which measure counts only new cases? (b) A long-lasting, survivable condition inflates which measure? Answers: incidence; prevalence."}]}'::jsonb, 'Prevalence is a proportion (no time in it); an incidence rate has person-time in the denominator, so its units look like ''cases per person-year''.', 14),
  (4, 'Study designs: cohort, case-control, cross-sectional, and trials', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Match a research question to a cohort, case-control, cross-sectional, or randomized design and explain the trade-off each makes. Warm-up: if a disease is very rare, would it be efficient to follow a huge group forward and wait for a handful of cases?"},{"heading":"The idea","text":"A cohort study starts with people grouped by exposure and follows them forward to see who develops the outcome; it yields incidence directly but is slow and costly for rare diseases. A case-control study starts with people grouped by outcome - cases and comparable controls - and looks backward at their exposures; it is efficient for rare diseases but cannot give incidence and is prone to recall problems. A cross-sectional study measures exposure and outcome at the same moment, giving prevalence and associations but no time order. A randomized controlled trial assigns the exposure or treatment by chance; randomization tends to balance both known and unknown confounders, making it the strongest design for causation, though ethics and cost limit where it can be used."},{"heading":"Worked examples","text":"To study whether a common workplace exposure raises the risk of a common respiratory outcome, a cohort study enrolls exposed and unexposed workers and follows both for five years. To study a rare cancer, a case-control study instead recruits 200 patients with the cancer and 200 similar controls and compares how many in each group were exposed years earlier - far cheaper than following millions forward. To estimate how many adults in a city currently have a condition and whether it tracks with a habit, a cross-sectional survey measures both at once. To test whether a new preventive regimen truly lowers risk, a randomized trial flips a coin to assign each volunteer to the regimen or a placebo, then compares outcomes."},{"heading":"Your turn","text":"1) Which design measures incidence directly? 2) For a very rare disease, which observational design is most efficient? 3) Which single design best balances unknown confounders, and why? 4) A survey measures diet and blood pressure on the same day - what design is that, and what can''t it establish? 5) Which design is most vulnerable to people misremembering past exposure? Answers: 1) the cohort study. 2) the case-control study. 3) the randomized controlled trial, because random assignment tends to balance known and unknown factors across groups. 4) cross-sectional; it cannot establish which came first. 5) the case-control study (recall bias)."},{"heading":"Common mistakes & exit ticket","text":"Mistake: expecting a case-control study to report incidence - it starts from cases, so it cannot. Mistake: reading a cross-sectional association as a cause because it feels temporal; the snapshot has no time order. Exit: (a) Cohort studies group people by what? (b) Case-control studies group people by what? Answers: exposure; outcome."}]}'::jsonb, 'Cohort studies group people by exposure and wait for outcomes; case-control studies group people by outcome and look back at exposure. The starting axis is the fastest way to name a design.', 15),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"A survey finds 250 current cases in a population of 5,000. The prevalence is...","options":["2 percent","5 percent","10 percent","25 percent"],"answer":1,"explanation":"250 / 5,000 = 0.05 = 5 percent."},{"prompt":"Among 1,000 disease-free people followed one year, 30 develop the condition. The cumulative incidence is...","options":["3 percent","30 percent","0.3 percent","3 per 1,000 lifetime"],"answer":0,"explanation":"30 / 1,000 = 0.03 = 3 percent over the year."},{"prompt":"Which measure has person-time in its denominator?","options":["point prevalence","cumulative incidence","an incidence rate","an odds ratio"],"answer":2,"explanation":"An incidence rate divides new cases by total at-risk person-time."},{"prompt":"A study enrolls exposed and unexposed people and follows them forward for new cases. This is a...","options":["case-control study","cohort study","cross-sectional survey","ecological study"],"answer":1,"explanation":"Grouping by exposure and following forward defines a cohort study."},{"prompt":"The design that assigns exposure by chance to balance confounders is the...","options":["cross-sectional survey","case-control study","randomized controlled trial","case report"],"answer":2,"explanation":"Random assignment tends to balance both known and unknown confounders."},{"prompt":"A long-lasting condition that people survive for many years will tend to have a high...","options":["incidence rate","prevalence","case fatality","sensitivity"],"answer":1,"explanation":"Duration inflates prevalence: more people are living with it at any moment."}]}'::jsonb, null, 8),
  (6, 'Measures of association: risk ratio and odds ratio', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Lay out a 2x2 table, compute a risk ratio and an odds ratio, and interpret each against the no-effect value of 1. Warm-up: if the risk of an outcome is 9 percent in exposed people and 3 percent in unexposed people, roughly how many times higher is the exposed risk?"},{"heading":"The idea","text":"Arrange counts in a 2x2 table: exposed cases a, exposed non-cases b, unexposed cases c, unexposed non-cases d. The risk in the exposed is a/(a+b); the risk in the unexposed is c/(c+d). The risk ratio (relative risk) is the first divided by the second. The odds of disease in the exposed are a/b, in the unexposed c/d, so the odds ratio is (a/b)/(c/d) = ad/bc. A value of 1 means no association; above 1 suggests higher risk with exposure, below 1 suggests lower. When a disease is rare, the odds ratio closely approximates the risk ratio, which is why case-control studies - which cannot compute risk directly - still inform us about relative risk."},{"heading":"Worked examples","text":"Take a = 90, b = 910, c = 30, d = 970, so 1,000 exposed and 1,000 unexposed. Risk in exposed = 90/1000 = 0.09; risk in unexposed = 30/1000 = 0.03. Risk ratio = 0.09 / 0.03 = 3.0, so exposed people have three times the risk. Odds ratio = ad/bc = (90 * 970) / (910 * 30) = 87,300 / 27,300 = 3.20 - close to the risk ratio because the disease is fairly uncommon. Now a rarer outcome: a = 10, b = 990, c = 5, d = 995. Risk ratio = (10/1000)/(5/1000) = 2.0; odds ratio = (10*995)/(990*5) = 9,950/4,950 = 2.01, almost identical."},{"heading":"Your turn","text":"1) With a = 40, b = 160, c = 20, d = 180, what is the risk in the exposed group? 2) What is the risk ratio for that table? 3) Compute the odds ratio for a = 40, b = 160, c = 20, d = 180. 4) A risk ratio of exactly 1 means what? 5) When does the odds ratio best approximate the risk ratio? Answers: 1) 40/(40+160) = 40/200 = 0.20. 2) unexposed risk = 20/200 = 0.10, so risk ratio = 0.20/0.10 = 2.0. 3) ad/bc = (40*180)/(160*20) = 7,200/3,200 = 2.25. 4) no association between exposure and outcome. 5) when the outcome is rare."},{"heading":"Common mistakes & exit ticket","text":"Mistake: computing a risk ratio from case-control data, where the case-to-control ratio is set by the investigator, not by nature. Mistake: reading an odds ratio of 3 as ''three times the risk'' when the disease is common - the two diverge as the outcome gets frequent. Exit: (a) What no-effect value do both ratios center on? (b) Which ratio can a case-control study legitimately report? Answers: 1; the odds ratio."}]}'::jsonb, 'The risk ratio needs full denominators (a+b and c+d), so it belongs to cohort and trial data; the odds ratio uses only ad/bc, which is why case-control studies report it.', 15),
  (7, 'Bias and confounding', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Tell selection bias from information bias, recognize confounding, and name a fix for each. Warm-up: if a study of a strenuous hobby and heart health only enrolls people healthy enough to keep doing the hobby, which group has quietly been filtered out?"},{"heading":"The idea","text":"Bias is a systematic error that pushes a result away from the truth in a consistent direction. Selection bias arises when who gets into the study (or stays in it) is linked to both exposure and outcome - for example, enrolling only the survivors, or losing sicker people to follow-up. Information bias arises from how exposure or outcome is measured - misclassifying who was exposed, or cases recalling past exposures more eagerly than controls (recall bias). Confounding is different: it is a genuine effect of a third variable that is associated with the exposure and independently affects the outcome, muddying the exposure-outcome link. The classic example: coffee drinking looks tied to lung disease only because coffee drinkers smoked more - smoking is the confounder."},{"heading":"Worked examples","text":"Selection bias: a hospital study compares patients and finds two conditions oddly linked, but the link exists only because having either condition raises the chance of being admitted (Berkson''s bias). Information bias: mothers of children with a birth condition search their memories harder for pregnancy exposures than mothers of healthy children, inflating the exposure difference (recall bias). Confounding: a raw comparison shows heavy coffee drinkers have more lung disease, apparent risk ratio 2.0; but when you compare within smokers and within non-smokers separately, the coffee association vanishes, showing smoking was the real driver. That last move - analyzing within levels of the third variable - is called stratification, one way to adjust for a measured confounder."},{"heading":"Your turn","text":"1) A study loses its sickest participants before follow-up ends - which broad category of error is that? 2) Cases remember exposures more vividly than controls - name the specific bias. 3) A variable tied to both exposure and outcome that distorts their link is a what? 4) Name one analytic method to handle a measured confounder. 5) Can randomization reduce confounding by variables you did not even measure? Answers: 1) selection bias. 2) recall bias (a form of information bias). 3) confounder. 4) stratification (or multivariable adjustment). 5) yes - random assignment tends to balance unmeasured factors too."},{"heading":"Common mistakes & exit ticket","text":"Mistake: calling every distortion ''bias'' - confounding is a real effect of a third variable, not a measurement flaw. Mistake: believing you can adjust for a confounder you never recorded; only measured confounders can be adjusted in analysis. Exit: (a) Selection bias is about what step? (b) What kind of variable is a confounder relative to exposure and outcome? Answers: who enters or stays in the study; one associated with the exposure and independently affecting the outcome."}]}'::jsonb, 'Bias is a flaw in how data were gathered or measured; confounding is a real third-variable effect. You fix bias in the design; you can adjust for a measured confounder in the analysis.', 14),
  (8, 'Causal inference and the Bradford Hill considerations', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain why association is not causation and apply Bradford Hill''s considerations to weigh a causal claim. Warm-up: if two things rise together, name at least two innocent explanations besides ''one causes the other''."},{"heading":"The idea","text":"An association can arise from chance, bias, confounding, reverse causation, or a true causal effect - so a correlation alone never settles cause. In 1965 Austin Bradford Hill offered considerations that make a causal reading more or less credible: temporality (the cause precedes the effect), strength (a large association is harder to explain away), consistency (many studies in different settings agree), a biological gradient or dose-response (more exposure, more effect), plausibility and coherence (a believable mechanism that fits what else is known), specificity (a tight exposure-outcome link), experiment (intervening changes the outcome), and analogy (similar causes act similarly). No single item proves cause, and only temporality is close to essential; the others accumulate into a judgment."},{"heading":"Worked examples","text":"The smoking and lung cancer case scores well across the board: smoking preceded disease (temporality), the association was strong (many-fold higher risk), it repeated across countries and designs (consistency), heavier smoking meant higher risk (dose-response), and a mechanism involving carcinogens was plausible and coherent. Contrast a spurious pairing: ice-cream sales and drowning deaths rise together, but hot weather drives both - a confounder - and there is no dose-response or mechanism linking cones to drowning, so the causal reading fails. Reverse causation trap: early fatigue may look like it follows a diagnosis, when in fact undiagnosed disease was already causing the fatigue, flipping the assumed time order."},{"heading":"Your turn","text":"1) Which Bradford Hill consideration is closest to required? 2) ''Higher dose, larger effect'' names which consideration? 3) Name two non-causal reasons two variables might move together. 4) Does agreement across many independent studies speak to strength or consistency? 5) Why do ice-cream sales and drownings correlate? Answers: 1) temporality. 2) biological gradient (dose-response). 3) any two of chance, bias, confounding, reverse causation. 4) consistency. 5) a shared confounder - hot weather raises both."},{"heading":"Common mistakes & exit ticket","text":"Mistake: tallying the criteria like a scorecard and declaring cause at some count - they inform judgment, not arithmetic. Mistake: ignoring reverse causation, where the outcome was actually shaping the supposed exposure. Exit: (a) Name three things besides causation that can create an association. (b) Which consideration is nearly non-negotiable? Answers: chance, bias, confounding (also reverse causation); temporality."}]}'::jsonb, 'These are considerations, not a checklist to tally. Temporality is close to required; the rest add or subtract weight from a causal argument.', 14),
  (9, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"With a = 60, b = 140, c = 30, d = 170, the risk in the exposed group is...","options":["0.15","0.30","0.60","0.43"],"answer":1,"explanation":"a/(a+b) = 60/200 = 0.30."},{"prompt":"For that same table, the risk ratio (exposed vs unexposed) is...","options":["1.0","1.5","2.0","3.0"],"answer":2,"explanation":"Unexposed risk = 30/200 = 0.15; risk ratio = 0.30/0.15 = 2.0."},{"prompt":"The odds ratio for a = 60, b = 140, c = 30, d = 170 is closest to...","options":["1.0","2.4","3.0","0.5"],"answer":1,"explanation":"ad/bc = (60*170)/(140*30) = 10,200/4,200 = 2.43."},{"prompt":"Cases recalling past exposures more thoroughly than controls is an example of...","options":["selection bias","information (recall) bias","confounding","random error"],"answer":1,"explanation":"Differential recall is a measurement problem, hence information bias."},{"prompt":"A raw coffee-disease link that disappears once you compare within smokers and non-smokers illustrates...","options":["reverse causation","confounding by smoking","selection bias","a dose-response effect"],"answer":1,"explanation":"Smoking is associated with coffee and affects the outcome, so it confounded the crude link."},{"prompt":"Which Bradford Hill consideration is closest to a strict requirement for causation?","options":["analogy","specificity","temporality","plausibility"],"answer":2,"explanation":"A cause must come before its effect in time."}]}'::jsonb, null, 8),
  (10, 'Screening and diagnostic tests: sensitivity, specificity, predictive values', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Build a test-by-truth 2x2 table and compute sensitivity, specificity, and predictive values, and explain why prevalence changes the predictive values. Warm-up: if a test almost never misses true cases but often alarms healthy people, is it strong on sensitivity or on specificity?"},{"heading":"The idea","text":"Cross the test result against the truth: true positives TP (test positive, disease present), false negatives FN (test negative, disease present), false positives FP (test positive, disease absent), and true negatives TN (test negative, disease absent). Sensitivity = TP/(TP+FN), the share of true cases the test catches. Specificity = TN/(TN+FP), the share of truly healthy people it clears. These describe the test regardless of prevalence. Predictive values answer the patient''s question: positive predictive value PPV = TP/(TP+FP), the chance a positive result is real; negative predictive value NPV = TN/(TN+FN), the chance a negative is real. Crucially, PPV and NPV shift with prevalence - the same test yields more false alarms when disease is rare."},{"heading":"Worked examples","text":"Test 1,000 people where 100 truly have the condition. Results: TP = 80, FN = 20, FP = 90, TN = 810. Sensitivity = 80/(80+20) = 80 percent. Specificity = 810/(810+90) = 90 percent. PPV = 80/(80+90) = 80/170 = 47 percent - fewer than half of positives are real, because the condition is uncommon. NPV = 810/(810+20) = 810/830 = 97.6 percent. Now run the same test where disease is rarer, say 10 true cases in 1,000: with 80 percent sensitivity you catch 8 (FN 2), and 90 percent specificity on 990 healthy people gives about 99 false positives. PPV = 8/(8+99) = 7.5 percent - the identical test is far less convincing on a positive when prevalence drops."},{"heading":"Your turn","text":"1) With TP = 45, FN = 5, FP = 100, TN = 850, what is the sensitivity? 2) What is the specificity? 3) What is the PPV? 4) Which two measures depend on prevalence? 5) In a low-prevalence screen, does a positive result become more or less trustworthy? Answers: 1) 45/(45+5) = 45/50 = 90 percent. 2) 850/(850+100) = 850/950 = 89.5 percent. 3) 45/(45+100) = 45/145 = 31 percent. 4) PPV and NPV. 5) less trustworthy - false positives swamp the few true cases."},{"heading":"Common mistakes & exit ticket","text":"Mistake: reporting a positive result as near-certain in a low-prevalence setting, ignoring the flood of false positives. Mistake: swapping sensitivity and specificity - sensitivity is about true cases caught, specificity about healthy people cleared. Exit: (a) Which measure is TP/(TP+FN)? (b) Why can the same test have different PPV in two populations? Answers: sensitivity; because PPV depends on prevalence, which differs between populations."}]}'::jsonb, 'Sensitivity and specificity are properties of the test itself; predictive values also depend on how common the disease is in the tested group (its prevalence).', 15),
  (11, 'Outbreak investigation', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"List the core steps of an outbreak investigation, read an epidemic curve, and use attack rates to point at a source. Warm-up: after a shared banquet, if you wanted to find the culprit dish, whose plates would you compare - the ill guests'' choices against the well guests'' choices?"},{"heading":"The idea","text":"An outbreak is more cases than expected in a place and time. Investigators move through recognizable steps: confirm the outbreak is real and the diagnosis is right, define a case with clear criteria, find and count cases, describe them by person, place, and time (including an epidemic curve of onsets), form a hypothesis about the source, test it by comparing exposures between ill and well people, and then act to control spread. A key tool is the attack rate: among people who ate a given food, the proportion who fell ill. The suspect exposure is the one with a high attack rate among the exposed, a low rate among the unexposed, and that most of the sick people shared."},{"heading":"Worked examples","text":"At a banquet, 50 guests ate the potato salad and 40 of them fell ill, an attack rate of 40/50 = 80 percent; among the 50 who skipped it, only 5 fell ill, a rate of 5/50 = 10 percent. That gap (80 percent versus 10 percent) points hard at the potato salad. A second dish, the bread, shows attack rates of 46 percent among eaters and 44 percent among non-eaters - nearly equal, so bread is exonerated. The epidemic curve shows a single sharp spike of onsets a few hours after the meal, consistent with one common-source exposure rather than ongoing person-to-person transmission, which would produce successive waves spaced by the incubation period."},{"heading":"Your turn","text":"1) Among 30 punch drinkers, 24 fell ill - what is the attack rate? 2) A food shows nearly equal attack rates in eaters and non-eaters; is it a likely source? 3) A single tall spike on the epidemic curve suggests what kind of source? 4) Which two groups'' exposures do you compare to find the culprit? 5) What is the first step, before hunting for a source? Answers: 1) 24/30 = 80 percent. 2) no - a real source shows a much higher rate among the exposed. 3) a common-source (single shared) exposure. 4) the ill and the well. 5) confirm the outbreak and the diagnosis are real."},{"heading":"Common mistakes & exit ticket","text":"Mistake: blaming the food most sick people ate without checking the well people - if the well ate it just as often, it is not the source. Mistake: skipping a clear case definition, so the count drifts. Exit: (a) What does an attack rate measure? (b) What curve shape suggests person-to-person spread? Answers: the proportion of an exposed group that becomes ill; successive waves spaced by the incubation period."}]}'::jsonb, 'An epidemic curve plots case counts by time of onset. Its shape hints at the source: a sharp single peak suggests one common exposure; rolling peaks suggest person-to-person spread.', 13),
  (12, 'Infectious disease dynamics: R0 and herd immunity (education)', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Interpret the basic reproduction number, compute a herd immunity threshold, and explain why an epidemic fades once Re falls below 1. This section is educational modeling, not medical advice. Warm-up: if each case, on average, produces exactly one new case, is the outbreak growing, shrinking, or holding steady?"},{"heading":"The idea","text":"The basic reproduction number R0 is the average number of new infections one case causes in a fully susceptible population. If R0 is above 1, cases multiply; below 1, the chain dies out; at exactly 1, it holds steady. As people gain immunity, susceptibles shrink, and the effective reproduction number Re = R0 times the susceptible fraction is what matters. Herd immunity is the point where enough people are immune that Re drops below 1 and each case, on average, fails to replace itself, protecting even the non-immune. The threshold fraction that must be immune is 1 - 1/R0. This is a simplified model; real spread also depends on contact patterns, timing, and behavior."},{"heading":"Worked examples","text":"If R0 = 4, the herd immunity threshold is 1 - 1/4 = 0.75, so about 75 percent of the population must be immune before spread stalls. For a more transmissible pathogen with R0 = 10, the threshold rises to 1 - 1/10 = 0.90, i.e. 90 percent. For R0 = 2, it is 1 - 1/2 = 0.50. Now suppose R0 = 4 and 60 percent are already immune, leaving a susceptible fraction of 0.40: Re = 4 * 0.40 = 1.6, still above 1, so cases keep growing. Raise immunity to 80 percent and Re = 4 * 0.20 = 0.8, below 1, so the outbreak recedes."},{"heading":"Your turn","text":"1) For R0 = 5, what is the herd immunity threshold? 2) An outbreak with Re = 1 is doing what? 3) If R0 = 3 and half the population is susceptible, what is Re, and is spread growing? 4) Does a higher R0 raise or lower the immunity threshold? 5) At R0 = 2, what fraction must be immune? Answers: 1) 1 - 1/5 = 0.80 = 80 percent. 2) holding steady - each case replaces itself exactly. 3) Re = 3 * 0.5 = 1.5, above 1, so still growing. 4) raises it. 5) 1 - 1/2 = 0.50 = 50 percent."},{"heading":"Common mistakes & exit ticket","text":"Mistake: treating R0 as fixed reality when it assumes everyone is susceptible and ignores changing behavior. Mistake: thinking an epidemic only ends when everyone is infected - it turns the corner once Re falls below 1. Exit: (a) Write the herd immunity threshold formula. (b) What quantity actually governs whether cases grow day to day? Answers: 1 - 1/R0; the effective reproduction number Re."}]}'::jsonb, 'R0 assumes a fully susceptible population. Once some are immune, the effective reproduction number Re = R0 times the susceptible fraction is what actually governs spread.', 14),
  (13, 'Checkpoint 3', 'quiz', '{"questions":[{"prompt":"A test on 1,000 people gives TP = 90, FN = 10, FP = 180, TN = 720. The sensitivity is...","options":["80 percent","90 percent","50 percent","72 percent"],"answer":1,"explanation":"TP/(TP+FN) = 90/100 = 90 percent."},{"prompt":"For that same test, the specificity is...","options":["80 percent","90 percent","33 percent","72 percent"],"answer":0,"explanation":"TN/(TN+FP) = 720/900 = 80 percent."},{"prompt":"For that test, the positive predictive value is closest to...","options":["33 percent","50 percent","90 percent","80 percent"],"answer":0,"explanation":"PPV = TP/(TP+FP) = 90/270 = 33 percent."},{"prompt":"At a picnic, 45 of 50 people who ate a dish fell ill while 5 of 50 who skipped it fell ill. The attack rate among eaters is...","options":["10 percent","45 percent","90 percent","50 percent"],"answer":2,"explanation":"45/50 = 90 percent among eaters, far above 10 percent among non-eaters."},{"prompt":"For a pathogen with R0 = 5, the herd immunity threshold is...","options":["20 percent","50 percent","80 percent","100 percent"],"answer":2,"explanation":"1 - 1/5 = 0.80 = 80 percent."},{"prompt":"If R0 = 4 and the susceptible fraction is 0.20, the effective reproduction number Re is...","options":["0.8","4.0","2.0","1.2"],"answer":0,"explanation":"Re = 4 * 0.20 = 0.8, below 1, so the outbreak recedes."}]}'::jsonb, null, 8),
  (14, 'Interpreting evidence: a capstone case', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Walk a single reported finding through frequency, design, association, bias, confounding, and causal judgment - the whole course in one pass. Warm-up: when a headline says an exposure ''doubles the risk'', what three questions should you ask before believing it?"},{"heading":"The case","text":"Suppose a case-control study of a rare condition reports that people with the condition were more likely to have used a certain product: among 200 cases, 80 had used it; among 200 controls, 40 had used it. First, note the design - case-control, chosen because the condition is rare, which means we report an odds ratio, not a risk. Build the table: exposed cases a = 80, unexposed cases c = 120, exposed controls b = 40, unexposed controls d = 160. The odds ratio is ad/bc = (80 * 160) / (40 * 120) = 12,800 / 4,800 = 2.67. So the exposure is associated with about 2.7 times the odds of the condition."},{"heading":"Now interrogate it","text":"An odds ratio of 2.67 is only a starting point. Chance: is the sample large enough that this is unlikely to be a fluke? Selection bias: were controls chosen so their exposure reflects the source population, or were they, say, hospital patients with unusual exposures? Information bias: did cases, motivated to explain their illness, recall the product more thoroughly than controls (recall bias)? Confounding: is there a third factor - an age group or habit tied both to using the product and to the condition - that could be doing the work; can we stratify to check? Reverse causation: could early, undiagnosed disease have prompted people to use the product, flipping the time order?"},{"heading":"Your turn","text":"1) Why does this design report an odds ratio rather than a risk ratio? 2) Recompute the odds ratio if a = 90, b = 40, c = 110, d = 160. 3) Name the bias where cases search their memories harder than controls. 4) How could you check whether age is confounding the link? 5) Which Bradford Hill consideration asks whether the exposure came before the condition? Answers: 1) it is a case-control study, so full risk denominators are not available. 2) ad/bc = (90*160)/(40*110) = 14,400/4,400 = 3.27. 3) recall bias. 4) stratify - compare the association within age groups (or adjust for age). 5) temporality."},{"heading":"The verdict & exit ticket","text":"A responsible reading: the study shows an association (odds ratio about 2.7), but before calling it causal we must judge chance, selection and information bias, confounding, and temporality, and look for consistency with other studies and a dose-response pattern. One study rarely settles a causal question; it earns its place in a larger, converging body of evidence - and none of this is a substitute for professional medical advice. Exit: (a) Association of 2.7 - does that alone prove causation? (b) List the four rival explanations to rule out first. Answers: no; chance, bias, confounding, and reverse causation."}]}'::jsonb, 'Before believing an association, run the checklist: could chance, bias, confounding, or reverse causation explain it? Only then weigh a causal reading.', 15),
  (15, 'Comprehensive final quiz', 'quiz', '{"questions":[{"prompt":"Epidemiology studies the distribution and determinants of health states in...","options":["single patients","populations","laboratory cell cultures","insurance ledgers"],"answer":1,"explanation":"Its unit of concern is the population, not the individual."},{"prompt":"A one-time survey finding 400 current cases among 8,000 people reports a prevalence of...","options":["2 percent","5 percent","8 percent","20 percent"],"answer":1,"explanation":"400/8,000 = 0.05 = 5 percent."},{"prompt":"Which measure counts only new cases over a period among those at risk?","options":["point prevalence","incidence","case fatality at diagnosis","specificity"],"answer":1,"explanation":"Incidence captures new cases arising over time in the at-risk group."},{"prompt":"A study that starts with cases and controls and looks backward at exposure is a...","options":["cohort study","case-control study","randomized trial","cross-sectional survey"],"answer":1,"explanation":"Grouping by outcome and looking back defines the case-control design."},{"prompt":"With a = 50, b = 150, c = 25, d = 175, the risk ratio (exposed vs unexposed) is...","options":["1.0","2.0","2.5","3.0"],"answer":1,"explanation":"Exposed risk 50/200 = 0.25; unexposed risk 25/200 = 0.125; ratio = 2.0."},{"prompt":"The odds ratio ad/bc for a = 50, b = 150, c = 25, d = 175 is closest to...","options":["1.0","2.3","3.0","0.5"],"answer":1,"explanation":"(50*175)/(150*25) = 8,750/3,750 = 2.33."},{"prompt":"A crude exposure-outcome link that vanishes after comparing within levels of a third variable reflects...","options":["selection bias","confounding","recall bias","random error"],"answer":1,"explanation":"The third variable was a confounder; stratifying removed its effect."},{"prompt":"Losing the sickest participants to follow-up before the study ends is a form of...","options":["confounding","selection bias","dose-response","high specificity"],"answer":1,"explanation":"Who remains in the study is tied to outcome, so it is selection bias."},{"prompt":"The Bradford Hill consideration that a cause must precede its effect is...","options":["strength","temporality","analogy","specificity"],"answer":1,"explanation":"Temporality is the consideration closest to a strict requirement."},{"prompt":"A test with TP = 60, FN = 40, FP = 50, TN = 850 has a sensitivity of...","options":["60 percent","40 percent","85 percent","94 percent"],"answer":0,"explanation":"TP/(TP+FN) = 60/100 = 60 percent."},{"prompt":"For that same test, the positive predictive value is closest to...","options":["55 percent","60 percent","94 percent","50 percent"],"answer":0,"explanation":"PPV = TP/(TP+FP) = 60/110 = 55 percent."},{"prompt":"For a pathogen with R0 = 4, the herd immunity threshold and the effect of R0 = 8 on that threshold are...","options":["75 percent, and 8 lowers it","75 percent, and 8 raises it to about 88 percent","25 percent, and 8 lowers it","50 percent, and 8 leaves it unchanged"],"answer":1,"explanation":"1 - 1/4 = 75 percent; a higher R0 (8) raises it to 1 - 1/8 = 87.5 percent."}]}'::jsonb, null, 12)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0004-0000-4000-8000-000000000029' and l.position = v.pos
);
